#!/usr/bin/env python3
from pathlib import Path

ROOT = Path.cwd()
comp = ROOT / "frontend" / "components" / "SignalsClient.tsx"
css_path = ROOT / "frontend" / "app" / "globals.css"

if not comp.exists():
    raise SystemExit("❌ 找不到 frontend/components/SignalsClient.tsx，請在 repo 根目錄執行。")
if not css_path.exists():
    raise SystemExit("❌ 找不到 frontend/app/globals.css，請在 repo 根目錄執行。")

bak = comp.with_suffix(comp.suffix + ".bak_v105")
if not bak.exists():
    bak.write_text(comp.read_text(encoding="utf-8"), encoding="utf-8")

comp.write_text('\'use client\';\n\nimport { useMemo, useState } from \'react\';\n\ntype AnyRow = Record<string, any>;\ntype SortKey = \'amount\' | \'lots\' | \'consensus\' | \'price\' | \'pct\' | \'status\';\ntype SortDir = \'asc\' | \'desc\';\n\nconst STATUS_ORDER: Record<string, number> = { 新增: 1, 加碼: 2, 減碼: 3, 刪除: 4, 異動: 5 };\n\nfunction num(v: any, fallback = 0): number {\n  if (v === null || v === undefined || v === \'\') return fallback;\n  const x = Number(String(v).replace(/,/g, \'\').replace(/[^\\d.-]/g, \'\'));\n  return Number.isFinite(x) ? x : fallback;\n}\n\nfunction firstNum(row: AnyRow, keys: string[], fallback = 0): number {\n  for (const k of keys) {\n    if (row && row[k] !== undefined && row[k] !== null && row[k] !== \'\') {\n      const v = num(row[k], NaN);\n      if (Number.isFinite(v)) return v;\n    }\n  }\n  return fallback;\n}\n\nfunction getCode(row: AnyRow): string {\n  return String(row.stock_code ?? row.code ?? \'\').trim();\n}\n\nfunction getName(row: AnyRow): string {\n  return String(row.stock_name ?? row.name ?? row.stockName ?? getCode(row)).trim();\n}\n\nfunction getPrice(row: AnyRow): number | null {\n  const v = firstNum(row, [\'price\', \'close_price\', \'close\', \'last_price\'], NaN);\n  return Number.isFinite(v) ? v : null;\n}\n\nfunction getPct(row: AnyRow): number | null {\n  const v = firstNum(row, [\'change_pct\', \'pct\', \'percent\', \'changePercent\'], NaN);\n  return Number.isFinite(v) ? v : null;\n}\n\nfunction getLots(row: AnyRow): number {\n  let v = firstNum(row, [\n    \'net_lots\', \'display_delta_lots\', \'change_lots\', \'delta_lots\',\n    \'lot_change\', \'shares_change\', \'delta_shares\',\n  ], 0);\n\n  // 兼容舊資料：若還是「股」，自動轉成「張」\n  if (Math.abs(v) >= 100000) v = v / 1000;\n  return v;\n}\n\nfunction rowStatus(row: AnyRow): string {\n  const s = String(row.status ?? row.type ?? \'\').trim();\n  if (s) return s;\n  const lots = getLots(row);\n  if (lots > 0) return \'加碼\';\n  if (lots < 0) return \'減碼\';\n  return \'異動\';\n}\n\nfunction getBuyCount(row: AnyRow): number {\n  const direct = firstNum(row, [\'add_etf_count\', \'add_count\', \'buy_count\', \'buy_etf_count\', \'increase_count\'], NaN);\n  if (Number.isFinite(direct)) return Math.max(0, Math.round(direct));\n  const status = rowStatus(row);\n  const etfCount = Math.max(0, Math.round(firstNum(row, [\'etf_count\', \'count\'], 0)));\n  return status === \'新增\' || status === \'加碼\' ? etfCount : 0;\n}\n\nfunction getSellCount(row: AnyRow): number {\n  const direct = firstNum(row, [\'reduce_etf_count\', \'sell_count\', \'sell_etf_count\', \'decrease_count\'], NaN);\n  if (Number.isFinite(direct)) return Math.max(0, Math.round(direct));\n  const status = rowStatus(row);\n  const etfCount = Math.max(0, Math.round(firstNum(row, [\'etf_count\', \'count\'], 0)));\n  return status === \'刪除\' || status === \'減碼\' ? etfCount : 0;\n}\n\nfunction getConsensusScore(row: AnyRow): number {\n  return getBuyCount(row) - getSellCount(row);\n}\n\nfunction getAmountBillion(row: AnyRow): number {\n  const v = firstNum(row, [\n    \'flow_billion\', \'money_billion\', \'amount_billion\',\n    \'delta_amount_billion\', \'delta_value_billion\',\n    \'net_amount_billion\', \'trade_amount_billion\',\n  ], NaN);\n\n  if (Number.isFinite(v)) return v;\n\n  const price = getPrice(row);\n  const lots = getLots(row);\n  if (price !== null && Number.isFinite(lots)) return price * lots * 1000 / 100000000;\n\n  return 0;\n}\n\nfunction getRows(data: any): AnyRow[] {\n  const src = data?.rows ?? data?.changes ?? data?.aggregate ?? data?.items ?? [];\n  return Array.isArray(src) ? src : [];\n}\n\nfunction mmdd(dateLike: any): string {\n  const s = String(dateLike ?? \'\').trim();\n  const m = s.match(/(\\d{4})-(\\d{2})-(\\d{2})/);\n  if (m) return `${m[2]}-${m[3]}`;\n  return s;\n}\n\nfunction fmt0(v: any): string {\n  const x = num(v, NaN);\n  if (!Number.isFinite(x)) return \'-\';\n  return Math.round(x).toLocaleString(\'zh-TW\');\n}\n\nfunction fmtPrice(v: number | null): string {\n  if (v === null || !Number.isFinite(v)) return \'-\';\n  return v.toLocaleString(\'zh-TW\', { maximumFractionDigits: v >= 100 ? 1 : 2 });\n}\n\nfunction fmtPct(v: number | null): string {\n  if (v === null || !Number.isFinite(v)) return \'-\';\n  const sign = v > 0 ? \'+\' : \'\';\n  return `${sign}${v.toFixed(2)}%`;\n}\n\nfunction fmtSigned(v: number, suffix = \'\'): string {\n  if (!Number.isFinite(v)) return \'-\';\n  if (Math.abs(v) < 0.01) return `0${suffix}`;\n  const sign = v > 0 ? \'+\' : \'\';\n  return `${sign}${Math.round(v).toLocaleString(\'zh-TW\')}${suffix}`;\n}\n\nfunction fmtBillion(v: number): string {\n  if (!Number.isFinite(v)) return \'-\';\n  const sign = v > 0 ? \'+\' : \'\';\n  const abs = Math.abs(v);\n  const digits = abs >= 100 ? 1 : abs >= 10 ? 1 : 2;\n  return `${sign}${v.toLocaleString(\'zh-TW\', { minimumFractionDigits: 0, maximumFractionDigits: digits })} 億`;\n}\n\nfunction toneByValue(v: number): \'up\' | \'down\' | \'flat\' {\n  if (v > 0) return \'up\';\n  if (v < 0) return \'down\';\n  return \'flat\';\n}\n\nfunction FocusCard({ title, item, tone }: { title: string; item?: AnyRow | null; tone: \'red\' | \'green\' }) {\n  if (!item) {\n    return (\n      <div className={`signal105-focus ${tone}`}>\n        <div className="signal105-focus-title">{title}</div>\n        <div className="signal105-empty">尚無有效訊號</div>\n      </div>\n    );\n  }\n\n  const price = getPrice(item);\n  const pct = getPct(item);\n  const lots = getLots(item);\n  const amount = getAmountBillion(item);\n  const buy = getBuyCount(item);\n  const sell = getSellCount(item);\n\n  return (\n    <div className={`signal105-focus ${tone}`}>\n      <div className="signal105-focus-title">{title}</div>\n      <div className="signal105-focus-name"><span>{getName(item)}</span><b>{getCode(item)}</b></div>\n      <div className="signal105-focus-price">{fmtPrice(price)} <span className={toneByValue(pct ?? 0)}>{fmtPct(pct)}</span></div>\n      <div className="signal105-focus-sub">\n        <span>淨額 <b className={toneByValue(amount)}>{fmtBillion(amount)}</b></span>\n        <span>張數 <b className={toneByValue(lots)}>{fmtSigned(lots, \'張\')}</b></span>\n        <span>買賣 <b>{buy}:{sell}</b></span>\n      </div>\n    </div>\n  );\n}\n\nfunction SortPill({ label, sortKey, activeKey, dir, onClick }: { label: string; sortKey: SortKey; activeKey: SortKey; dir: SortDir; onClick: (key: SortKey) => void }) {\n  const active = activeKey === sortKey;\n  return <button className={`signal105-pill sort ${active ? \'active\' : \'\'}`} onClick={() => onClick(sortKey)} type="button">{label} {active ? (dir === \'desc\' ? \'↓\' : \'↑\') : \'↕\'}</button>;\n}\n\nfunction StatusPill({ label, active, count, onClick }: { label: string; active: boolean; count: number; onClick: () => void }) {\n  return <button className={`signal105-pill status ${label} ${active ? \'active\' : \'\'}`} onClick={onClick} type="button">{label}<b>{count || 0}</b></button>;\n}\n\nfunction SignalRow({ row }: { row: AnyRow }) {\n  const status = rowStatus(row);\n  const price = getPrice(row);\n  const pct = getPct(row);\n  const amount = getAmountBillion(row);\n  const lots = getLots(row);\n  const buy = getBuyCount(row);\n  const sell = getSellCount(row);\n\n  return (\n    <div className="signal105-row">\n      <div className="signal105-main">\n        <div className="signal105-stock"><b>{getName(row)}</b><span>{getCode(row)}</span></div>\n        <div className="signal105-price"><b>{fmtPrice(price)}</b><span className={toneByValue(pct ?? 0)}>{fmtPct(pct)}</span></div>\n        <div className="signal105-status-wrap"><span className={`signal105-status ${status}`}>{status}</span></div>\n        <div className="signal105-amount"><small>淨額</small><b className={toneByValue(amount)}>{fmtBillion(amount)}</b></div>\n      </div>\n      <div className="signal105-meta">\n        <span>張數 <b className={toneByValue(lots)}>{fmtSigned(lots, \' 張\')}</b></span>\n        <span>多空共識 <b>買賣 {buy}:{sell}</b></span>\n      </div>\n    </div>\n  );\n}\n\nexport default function SignalsClient(props: any) {\n  const data = props?.data ?? props ?? {};\n  const sourceRows = getRows(data);\n\n  const [selectedStatuses, setSelectedStatuses] = useState<string[]>([\'新增\', \'刪除\', \'加碼\', \'減碼\']);\n  const [sortKey, setSortKey] = useState<SortKey>(\'amount\');\n  const [sortDir, setSortDir] = useState<SortDir>(\'desc\');\n\n  const rows = useMemo(() => {\n    const filtered = sourceRows.filter((r) => selectedStatuses.includes(rowStatus(r)));\n\n    const valueOf = (r: AnyRow) => {\n      switch (sortKey) {\n        case \'amount\': return Math.abs(getAmountBillion(r));\n        case \'lots\': return Math.abs(getLots(r));\n        case \'consensus\': return Math.abs(getConsensusScore(r));\n        case \'price\': return getPrice(r) ?? -Infinity;\n        case \'pct\': return Math.abs(getPct(r) ?? 0);\n        case \'status\': return STATUS_ORDER[rowStatus(r)] ?? 99;\n        default: return 0;\n      }\n    };\n\n    return [...filtered].sort((a, b) => {\n      const av = valueOf(a);\n      const bv = valueOf(b);\n      return sortDir === \'desc\' ? bv - av : av - bv;\n    });\n  }, [sourceRows, selectedStatuses, sortKey, sortDir]);\n\n  const summary = useMemo(() => {\n    const out: Record<string, number> = { 新增: 0, 刪除: 0, 加碼: 0, 減碼: 0 };\n    for (const r of sourceRows) {\n      const s = rowStatus(r);\n      if (out[s] !== undefined) out[s] += 1;\n    }\n    return out;\n  }, [sourceRows]);\n\n  const focus = useMemo(() => {\n    const usable = sourceRows.filter((r) => rowStatus(r) !== \'異動\');\n    const positive = usable.filter((r) => getAmountBillion(r) > 0);\n    const negative = usable.filter((r) => getAmountBillion(r) < 0);\n    const addLike = usable.filter((r) => [\'新增\', \'加碼\'].includes(rowStatus(r)));\n    const reduceLike = usable.filter((r) => [\'刪除\', \'減碼\'].includes(rowStatus(r)));\n\n    const maxBy = (arr: AnyRow[], fn: (x: AnyRow) => number) => arr.length ? [...arr].sort((a, b) => fn(b) - fn(a))[0] : null;\n    const minBy = (arr: AnyRow[], fn: (x: AnyRow) => number) => arr.length ? [...arr].sort((a, b) => fn(a) - fn(b))[0] : null;\n\n    return {\n      inflow: maxBy(positive, getAmountBillion),\n      outflow: minBy(negative, getAmountBillion),\n      mostAdd: maxBy(addLike, (r) => getBuyCount(r) * 1000000 + Math.abs(getLots(r))),\n      mostReduce: maxBy(reduceLike, (r) => getSellCount(r) * 1000000 + Math.abs(getLots(r))),\n    };\n  }, [sourceRows]);\n\n  const dataDate = data?.data_date ?? data?.latestDataDate ?? \'\';\n  const fetched = data?.fetched_etf_count ?? data?.includedEtfCount ?? 0;\n  const total = data?.total_etf_count ?? data?.totalEtfCount ?? 0;\n\n  function toggleStatus(s: string) {\n    setSelectedStatuses((prev) => prev.includes(s) ? prev.filter((x) => x !== s) : [...prev, s]);\n  }\n\n  function toggleSort(k: SortKey) {\n    if (sortKey === k) setSortDir((d) => (d === \'desc\' ? \'asc\' : \'desc\'));\n    else { setSortKey(k); setSortDir(\'desc\'); }\n  }\n\n  return (\n    <main className="page signals-v7-page signal105-page">\n      <div className="signals-title-block signal105-title-block">\n        <h2>今日訊號</h2>\n        <div className="signals-data-status ok">\n          已抓取 {fetched || total || 0} / {total || fetched || 0} 檔 ETF{dataDate ? `，資料日期 ${mmdd(dataDate)}` : \'\'}\n        </div>\n      </div>\n\n      <div className="signal105-focus-grid">\n        <FocusCard title="淨資金流入最多" item={focus.inflow} tone="red" />\n        <FocusCard title="淨資金流出最多" item={focus.outflow} tone="green" />\n        <FocusCard title="最多 ETF 加碼" item={focus.mostAdd} tone="red" />\n        <FocusCard title="最多 ETF 減碼" item={focus.mostReduce} tone="green" />\n      </div>\n\n      <section className="signal105-detail">\n        <h3>資金交易明細：共 {fmt0(rows.length)} 檔</h3>\n\n        <div className="signal105-pill-row">\n          <StatusPill label="新增" active={selectedStatuses.includes(\'新增\')} count={summary[\'新增\']} onClick={() => toggleStatus(\'新增\')} />\n          <StatusPill label="刪除" active={selectedStatuses.includes(\'刪除\')} count={summary[\'刪除\']} onClick={() => toggleStatus(\'刪除\')} />\n          <StatusPill label="加碼" active={selectedStatuses.includes(\'加碼\')} count={summary[\'加碼\']} onClick={() => toggleStatus(\'加碼\')} />\n          <StatusPill label="減碼" active={selectedStatuses.includes(\'減碼\')} count={summary[\'減碼\']} onClick={() => toggleStatus(\'減碼\')} />\n        </div>\n\n        <div className="signal105-pill-row sortrow">\n          <SortPill label="金額" sortKey="amount" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="張數" sortKey="lots" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="共識" sortKey="consensus" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="股價" sortKey="price" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="漲跌幅" sortKey="pct" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n          <SortPill label="狀態" sortKey="status" activeKey={sortKey} dir={sortDir} onClick={toggleSort} />\n        </div>\n\n        <div className="signal105-list">\n          {rows.length ? rows.map((row, idx) => <SignalRow key={`${getCode(row)}-${idx}`} row={row} />) : <div className="signal105-empty-list">目前沒有符合篩選的訊號。</div>}\n        </div>\n      </section>\n    </main>\n  );\n}\n', encoding="utf-8")

css = css_path.read_text(encoding="utf-8")
marker = "/* ===== V105 signal page: compact list instead of cards ===== */"
if marker not in css:
    css_path.write_text(css.rstrip() + "\n\n" + '\n/* ===== V105 signal page: compact list instead of cards ===== */\n.signal105-page {\n  padding-left: max(16px, env(safe-area-inset-left));\n  padding-right: max(16px, env(safe-area-inset-right));\n}\n\n.signal105-page .signal103-range,\n.signal105-page .signal103-label,\n.signal105-page .signal103-range-tabs,\n.signal105-page .signal104-focus-grid,\n.signal105-page .signal104-detail,\n.signal105-page .signal104-row,\n.signal105-page .signal104-list {\n  display: none !important;\n}\n\n.signal105-title-block h2 {\n  font-size: clamp(38px, 7vw, 52px);\n  line-height: 1.1;\n  margin-bottom: 8px;\n}\n\n.signal105-focus-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n  margin: 22px 0 28px;\n}\n\n.signal105-focus {\n  border-radius: 20px;\n  padding: 16px;\n  min-height: 190px;\n  border: 1.5px solid #e8eef6;\n  background: #fff;\n  overflow: hidden;\n}\n\n.signal105-focus.red { background: #fff7f8; border-color: #f5ccd2; }\n.signal105-focus.green { background: #f2fffa; border-color: #bfe8da; }\n\n.signal105-focus-title {\n  font-size: clamp(19px, 4.5vw, 24px);\n  font-weight: 950;\n  margin-bottom: 8px;\n}\n\n.signal105-focus.red .signal105-focus-title { color: #df5662; }\n.signal105-focus.green .signal105-focus-title { color: #25a67d; }\n\n.signal105-focus-name {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  font-size: clamp(20px, 4.9vw, 25px);\n  font-weight: 950;\n  color: #172033;\n  white-space: nowrap;\n}\n\n.signal105-focus-name b {\n  font-size: 16px;\n  color: #8a96a8;\n}\n\n.signal105-focus-price {\n  font-size: clamp(30px, 7vw, 39px);\n  font-weight: 950;\n  line-height: 1.08;\n  margin: 5px 0 8px;\n  color: #df5662;\n  white-space: nowrap;\n}\n\n.signal105-focus-price span {\n  font-size: clamp(16px, 3.7vw, 20px);\n}\n\n.signal105-focus-sub {\n  display: grid;\n  gap: 2px;\n  font-size: 14px;\n  font-weight: 900;\n  color: #8190a4;\n}\n\n.signal105-focus-sub b { font-weight: 950; }\n\n.signal105-detail h3 {\n  font-size: clamp(31px, 6.4vw, 42px);\n  line-height: 1.15;\n  margin: 8px 0 16px;\n}\n\n.signal105-pill-row {\n  display: flex;\n  gap: 10px;\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n  padding: 2px 0 10px;\n  scrollbar-width: none;\n}\n\n.signal105-pill-row::-webkit-scrollbar { display: none; }\n\n.signal105-pill {\n  flex: 0 0 auto;\n  border-radius: 999px;\n  border: 2px solid #cbd5e1;\n  background: #fff;\n  color: #667386;\n  font-size: 20px;\n  font-weight: 950;\n  padding: 10px 15px;\n  min-height: 44px;\n}\n\n.signal105-pill b { margin-left: 5px; }\n\n.signal105-pill.status.新增.active { color: #b99a00; border-color: #c7aa00; background: #fffdea; }\n.signal105-pill.status.刪除.active { color: #6b7280; border-color: #a7b0bd; background: #f8fafc; }\n.signal105-pill.status.加碼.active { color: #df5662; border-color: #df5662; background: #fff7f8; }\n.signal105-pill.status.減碼.active { color: #22a77d; border-color: #22a77d; background: #f2fffa; }\n.signal105-pill.sort.active { color: #2f6fcc; border-color: #bfdbfe; background: #eff6ff; }\n\n.signal105-list { margin-top: 2px; }\n\n.signal105-row {\n  border-bottom: 1px solid #e6edf5;\n  padding: 16px 0 14px;\n}\n\n.signal105-main {\n  display: grid;\n  grid-template-columns: minmax(92px, 1.05fr) minmax(72px, 0.72fr) minmax(58px, 0.58fr) minmax(90px, 0.9fr);\n  column-gap: 10px;\n  align-items: center;\n}\n\n.signal105-stock b {\n  display: block;\n  font-size: clamp(22px, 5.5vw, 30px);\n  font-weight: 950;\n  color: #172033;\n  line-height: 1.1;\n}\n\n.signal105-stock span {\n  display: block;\n  font-size: 18px;\n  font-weight: 850;\n  color: #8b98aa;\n  margin-top: 2px;\n}\n\n.signal105-price b {\n  display: block;\n  font-size: clamp(21px, 5vw, 28px);\n  font-weight: 950;\n  color: #172033;\n  line-height: 1.05;\n  white-space: nowrap;\n}\n\n.signal105-price span {\n  display: block;\n  font-size: 17px;\n  font-weight: 950;\n  margin-top: 3px;\n  white-space: nowrap;\n}\n\n.signal105-status-wrap { text-align: center; }\n\n.signal105-status {\n  display: inline-flex;\n  border-radius: 999px;\n  padding: 6px 10px;\n  font-size: 17px;\n  font-weight: 950;\n  background: #eef2f7;\n  color: #64748b;\n  white-space: nowrap;\n}\n\n.signal105-status.新增 { background: #fff6bf; color: #b59a00; }\n.signal105-status.加碼 { background: #ffecef; color: #df5662; }\n.signal105-status.減碼, .signal105-status.刪除 { background: #eafaf4; color: #25a67d; }\n\n.signal105-amount { text-align: right; }\n\n.signal105-amount small {\n  display: block;\n  color: #8390a3;\n  font-size: 13px;\n  font-weight: 900;\n  line-height: 1.1;\n  margin-bottom: 2px;\n}\n\n.signal105-amount b {\n  display: block;\n  font-size: clamp(18px, 4.4vw, 24px);\n  font-weight: 950;\n  white-space: nowrap;\n}\n\n.signal105-meta {\n  margin-top: 8px;\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: 6px 14px;\n  color: #7f8da0;\n  font-size: 16px;\n  font-weight: 900;\n}\n\n.signal105-meta b {\n  font-weight: 950;\n  color: #172033;\n}\n\n.signal105-empty, .signal105-empty-list {\n  color: #7f8da0;\n  font-size: 18px;\n  font-weight: 900;\n  padding: 10px 0;\n}\n\n.signal105-empty-list {\n  border: 1px dashed #d6e0ec;\n  border-radius: 16px;\n  padding: 22px;\n}\n\n.signal105-page .up { color: #df5662 !important; }\n.signal105-page .down { color: #25a67d !important; }\n.signal105-page .flat { color: #7f8da0 !important; }\n\n@media (max-width: 430px) {\n  .signal105-focus-grid { gap: 10px; }\n  .signal105-focus { padding: 14px 12px; min-height: 180px; }\n  .signal105-focus-sub { font-size: 13px; }\n  .signal105-pill { font-size: 18px; padding: 9px 13px; }\n\n  .signal105-main {\n    grid-template-columns: minmax(96px, 1fr) minmax(76px, 0.78fr) minmax(56px, 0.56fr) minmax(82px, 0.82fr);\n    column-gap: 7px;\n  }\n\n  .signal105-status {\n    font-size: 15px;\n    padding: 5px 8px;\n  }\n\n  .signal105-meta {\n    font-size: 15px;\n    justify-content: flex-end;\n    gap: 4px 10px;\n  }\n}\n' + "\n", encoding="utf-8")

readme = ROOT / "README_V105_SIGNAL_COMPACT_LIST.md"
readme.write_text("""# V105 Signal compact list

修正內容：
1. 下方資金交易明細由卡片改回緊湊列表，不再使用大灰底卡片。
2. 每列主資訊維持一列：股票、股價、狀態、交易淨額。
3. 張數與多空共識移到第二行補充資訊，避免手機畫面擠在一起。
4. 保留排序：金額、張數、共識、股價、漲跌幅、狀態。
5. 保留上方四張重點摘要卡。
""", encoding="utf-8")

print("✅ V105 已完成：資金交易明細改為緊湊列表，保留張數、多空共識與排序。")
print("請接著 git add / commit / push，等 Vercel Ready 後重整。")
